from authlib.integrations.flask_client import OAuth

import os

from flask import Flask, redirect, url_for, session, request, jsonify



app = Flask(__name__)



oauth = OAuth(app)



oauth.register(

    name='auth0',

    client_id=os.environ.get('AUTH0_CLIENT_ID'),

    client_secret=os.environ.get('AUTH0_CLIENT_SECRET'),

    authorize_url='https://your_domain.auth0.com/authorize',

    access_token_url='https://your_domain.auth0.com/oauth/token',

    client_kwargs={

        'scope': 'openid profile email',

    },



@app.route('/login')

def login():

    return oauth.auth0.authorize_redirect(redirect_uri='http://localhost:3000/callback')



@app.route('/callback')

def callback():

    token = oauth.auth0.authorize_access_token()

    user = oauth.auth0.parse_id_token(token)

    session['profile'] = user

    return redirect(url_for('.user'))



@app.route('/user')

def user():

    return jsonify(session['profile'])

if __name__ == '__main__':

    app.secret_key = 'supersecret'

    app.run()

