import dropbox
from dropbox.exceptions import ApiError

class DropboxFileStorage:
    def __init__(self, access_token):
        self.dbx = dropbox.Dropbox(access_token)

    def upload_file(self, file_path, dest_path):
        with open(file_path, 'rb') as f:
            try:
                self.dbx.files_upload(f.read(), dest_path, mode=dropbox.files.WriteMode.add)
            except ApiError as e:
                print(f"Error uploading file: {e}")

    def list_versions(self, file_path):
        try:
            versions = self.dbx.files_list_revisions(file_path).entries
            return [entry.server_modified for entry in versions]
        except ApiError as e:
            print(f"Error listing file versions: {e}")
            return []

    def restore_version(self, file_path, version_date, dest_path):
        try:
            versions = self.dbx.files_list_revisions(file_path).entries
            for entry in versions:
                if entry.server_modified == version_date:
                    metadata, res = self.dbx.files_restore(file_path, entry.rev)
                    with open(dest_path, 'wb') as f:
                        f.write(res.content)
                    print(f"File restored to version from {version_date}")
                    return
            print("Version not found")
        except ApiError as e:
            print(f"Error restoring file version: {e}")

