access_token = 'ACCESS_TOKEN'

def fetch_user_feed(username):
    url = f'https://api.tiktok.com/user/{username}/feed'
    headers = {
        'Authorization': f'Bearer {access_token}'
    }
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        feed_data = response.json()
        return feed_data
    else:
        return None

def display_user_feed(feed_data):
    if feed_data:
        for post in feed_data['data']:
            if post['type'] == 'image':
                print(f"Image post: {post['image_url']}")
            elif post['type'] == 'video':
                print(f"Video post: {post['video_url']}")
            else:
                print(f"Text post: {post['text']}")

# Replace 'username' with the user's TikTok username
username = 'username'
user_feed = fetch_user_feed(username)
display_user_feed(user_feed)
