API_URL = "https://api.cloudflare.com/client/v4/accounts/{account_id}/stream"
API_KEY = "your_api_key"
ACCOUNT_ID = "your_account_id"
USER_ID = "user_id"

def get_upload_token(user_id, video_title):
    headers = {
        "Authorization": f"Bearer {API_KEY}",
        "Content-Type": "application/json"
    }
    data = {
        "rules": [
            {
                "name": "allow_user_upload",
                "value": f"user_id:{user_id}"
            }
        ],
        "title": video_title
    }
    response = requests.post(f"{API_URL}/tokens", json=data, headers=headers)
    return response.json()

def upload_video(upload_token, video_file):
    headers = {
        "Authorization": f"Bearer {upload_token['result']['token']}"
    }
    files = {
        "file": open(video_file, "rb")
    }
    response = requests.post(upload_token['result']['url'], files=files, headers=headers)
    return response.json()

def get_video(video_id):
    headers = {
        "Authorization": f"Bearer {API_KEY}"
    }
    response = requests.get(f"{API_URL}/videos/{video_id}", headers=headers)
    return response.json()

# Example usage
upload_token = get_upload_token(USER_ID, "My Video Title")
video_file_path = "path_to_video_file"
upload_response = upload_video(upload_token, video_file_path)
uploaded_video_id = upload_response['result']['id']
video_info = get_video(uploaded_video_id)
print(video_info)
```

Please note that you'll need to replace `your_api_key`, `your_account_id`, and `user_id` with your own Cloudflare Stream API key, account ID, and user ID. Also, replace `path_to_video_file` with the actual path to the video file you want to upload.`

