import requests

# Replace with your Mux API token
mux_token = "your_mux_api_token"

def create_interactive_video(video_id, interactive_elements):
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {mux_token}"
    }

    payload = {
        "data": {
            "type": "video_interactive",
            "attributes": {
                "video_id": video_id,
                "interactive_elements": interactive_elements
            }
        }
    }

    response = requests.post("https://api.mux.com/video/v1/interactive-videos", headers=headers, json=payload)

    if response.status_code == 201:
        print("Interactive video created successfully.")
    else:
        print(f"Failed to create interactive video. Status code: {response.status_code}")

# Example usage
