# Code to integrate Brightcove Interactive Video Features
import requests

def add_quiz_to_video(video_id, quiz_questions):
    # Code to add quiz questions to the specified video
    payload = {
        "video_id": video_id,
        "quiz_questions": quiz_questions
    }
    response = requests.post("https://api.brightcove.com/quiz/add", json=payload)
    return response.json()

def add_annotations_to_video(video_id, annotations_data):
    # Code to add annotations to the specified video
    payload = {
        "video_id": video_id,
        "annotations_data": annotations_data
    }
    response = requests.post("https://api.brightcove.com/annotations/add", json=payload)
    return response.json()

def add_clickable_links_to_video(video_id, link_data):
    # Code to add clickable links to the specified video
    payload = {
        "video_id": video_id,
        "link_data": link_data
    }
    response = requests.post("https://api.brightcove.com/clickable_links/add", json=payload)
    return response.json()

# Example usage
