# Import the necessary libraries
from googleapiclient.discovery import build
from google_auth_oauthlib.flow import InstalledAppFlow
from google.auth.transport.requests import Request
import os
import pickle
from apiclient.discovery import build
from oauth2client import client
from oauth2client import tools
from oauth2client.file import Storage

# Define the scope and credentials file
CLIENT_SECRETS_FILE = "client_secret.json"
SCOPES = ['https://www.googleapis.com/auth/youtube.force-ssl']

# Authenticate and create the YouTube Data API service
def get_authenticated_service():
    flow = client.flow_from_clientsecrets(CLIENT_SECRETS_FILE, SCOPES)
    storage = Storage("youtube_api_credential.json")
    credentials = storage.get()
    if credentials is None or credentials.invalid:
        credentials = tools.run_flow(flow, storage)
    return build('youtube', 'v3', credentials=credentials)

# Define the video ID and interactive elements
video_id = 'YOUR_VIDEO_ID'
interactive_data = {
    "annotation": {
        "startTime": "0s",
        "duration": "10s",
        "payload": "Check out our website for more information",
        "position": {
            "cornerPosition": "TOP_RIGHT"
        }
    },
    "link": {
        "startTime": "30s",
        "duration": "5s",
        "url": "http://www.example.com",
        "position": {
            "type": "CUSTOME",
            "xPos": 0.1,
            "yPos": 0.1
        }
    }
}

# Create the interactive elements using the YouTube Data API
def create_interactive_elements(youtube, video_id, interactive_data):
    for element_type, data in interactive_data.items():
        request = youtube.annotations().insert(
            part="snippet",
            body={
                "snippet": {
                    "videoId": video_id,
                    "text": data["payload"],
                    "position": data["position"],
                    "type": "note"
                }
            }
        ) if element_type == "annotation" else youtube.videoAbuseReportReasons().insert(
            part="snippet",
            body={
                "snippet": {
                    "videoId": video_id,
                    "url": data["url"],
                    "position": data["position"],
                    "type": "videoLink"
                }
            }
        )
        response = request.execute()
        print(f"{element_type} created: {response}")

# Authenticate the service and create the interactive elements
youtube = get_authenticated_service()
create_interactive_elements(youtube, video_id, interactive_data)
````

